     9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    10	public final class ReservationService {
    11	
    12	    private final Rooms rooms;
    13	    private final ReservationStore store;
    14	    private final PriceCalculator priceCalculator;
    15	    private final List<ReservationListener> listeners;
    16	
    17	    public ReservationService(
    18	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, List<ReservationListener> listeners) {
    19	        this.rooms = rooms;
    20	        this.store = store;
    21	        this.priceCalculator = priceCalculator;
    22	        this.listeners = List.copyOf(listeners);
    23	    }
    24	
    25	    public synchronized Reservation create(NewReservation request) {
    26	        if (!request.checkOut().isAfter(request.checkIn())) {
    27	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    28	        }
    29	        if (request.guests() < 1) {
    30	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    31	        }
    32	        Room room = rooms.find(request.roomNumber())
    33	                .orElseThrow(() -> new HotelException(
    34	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    35	        if (request.guests() > room.capacity()) {
    36	            throw new HotelException(
    37	                    ErrorCode.CAPACITY_EXCEEDED,
    38	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    39	        }
    40	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    41	            throw new HotelException(
    42	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    43	        }
    44	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    45	        return store.add(request, price);
    46	    }
    47	
    48	    public Reservation find(long reservationId) {
    49	        return store.find(reservationId)
    50	                .orElseThrow(() -> new HotelException(
    51	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    52	    }
    53	
    54	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    55	    public synchronized Reservation confirm(long reservationId) {
    56	        Reservation reservation = find(reservationId);
    57	        if (reservation.status() != ReservationStatus.PENDING) {
    58	            throw notAllowed(reservation, "confirm");
    59	        }
    60	        reservation.confirmPayment();
    61	        store.update(reservation);
    62	        Room room = roomOf(reservation);
    63	        for (ReservationListener listener : listeners) {
    64	            listener.onReservationConfirmed(reservation, room);
    65	        }
    66	        return reservation;
    67	    }
    68	
    69	    /**
    70	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    71	     * reservation was never paid, so nothing comes back).
    72	     */
    73	    public synchronized Reservation cancel(long reservationId) {
    74	        Reservation reservation = find(reservationId);
    75	        if (reservation.status() != ReservationStatus.PENDING
    76	                && reservation.status() != ReservationStatus.CONFIRMED) {
    77	            throw notAllowed(reservation, "cancel");
    78	        }
    79	        boolean wasPreviouslyConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
    80	        BigDecimal refund = switch (reservation.ratePlan()) {
    81	            case STANDARD -> reservation.amountPaid();
    82	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    83	        };
    84	        reservation.cancel(refund);
    85	        store.update(reservation);
    86	        Room room = roomOf(reservation);
    87	        for (ReservationListener listener : listeners) {
    88	            listener.onReservationCancelled(reservation, room, wasPreviouslyConfirmed);
    89	        }
    90	        return reservation;
    91	    }
    92	
    93	    public synchronized Reservation checkIn(long reservationId) {
    94	        Reservation reservation = find(reservationId);
    95	        if (reservation.status() != ReservationStatus.CONFIRMED) {
    96	            throw notAllowed(reservation, "check in");
    97	        }
    98	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
    99	        store.update(reservation);
   100	        return reservation;
   101	    }
   102	
   103	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   104	    public synchronized ReservationReceipt checkOut(long reservationId) {
   105	        Reservation reservation = find(reservationId);
   106	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   107	            throw notAllowed(reservation, "check out");
   108	        }
   109	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   110	        store.update(reservation);
   111	        return new ReservationReceipt(reservation, roomOf(reservation));
   112	    }
   113	
   114	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   115	    public ReservationReceipt receiptCopy(long reservationId) {
   116	        Reservation reservation = find(reservationId);
